raw_text:
{
  "narratives": [
    {
      "item_code": "S4_EYE",
      "title_raw": "가. 눈에 들어갔을 때",
      "start": "p2:L7",
      "end": "p2:L7"
    },
    {
      "item_code": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "start": "p2:L8",
      "end": "p2:L13"
    },
    {
      "item_code": "S4_INHAL",
      "title_raw": "다. 흡입했을 때",
      "start": "p2:L14",
      "end": "p2:L18"
    },
    {
      "item_code": "S4_INGEST",
      "title_raw": "라. 먹었을 때",
      "start": "p2:L19",
      "end": "p2:L19"
    },
    {
      "item_code": "S4_DOCTOR",
      "title_raw": "마. 기타 의사의 주의사항",
      "start": "p2:L20",
      "end": "p2:L20"
    }
  ],
  "extras": [
    {
      "after_item": "S4_EYE",
      "title_raw": "나. 피부에 접촉했을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "긴급 의료조치를 받으시오"
        ,
          "line": "p2:L8"
        },
        {
          "value": "피부에 얼어붙은 옷은 제거하기전 해동하시오"
        ,
          "line": "p2:L9"
        },
        {
          "value": "화상의 경우 즉시 찬물로 가능한 오래 해당부위를 식히고, 피부에 들러붙은"
        ,
          "line": "p2:L10"
        },
        {
          "value": "옷은 제거하지 마시오"
        ,
          "line": "p2:L11"
        },
        {
          "value": "가스 또는 액화 가스와 접촉 시 화상, 심각한 상해, 동상을 유발할 수 있음"
        ,
          "line": "p2:L12"
        },
        {
          "value": "불편함을 느끼면 의료기관(의사)의 진찰을 받으시오."
        ,
          "line": "p2:L13"
        }
      ]
    ,
      "suggested_code": "S4_SKIN"
    ,
      "line": "p2:L8"
    },
    {
      "after_item": "S4_SKIN",
      "title_raw": "다. 흡입했을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "과량의 가스에 노출된 경우 깨끗한 공기로 제거하고 기침이나 다른 증상이 있을 경우"
        ,
          "line": "p2:L14"
        },
        {
          "value": "의료 조치를 취하시오"
        ,
          "line": "p2:L15"
        },
        {
          "value": "긴급 의료조치를 받으시오"
        ,
          "line": "p2:L16"
        },
        {
          "value": "호흡하지 않는 경우 인공호흡을 실시하시오"
        ,
          "line": "p2:L17"
        },
        {
          "value": "호흡이 힘들 경우 산소를 공급하시오"
        ,
          "line": "p2:L18"
        }
      ]
    ,
      "suggested_code": "S4_INHAL"
    ,
      "line": "p2:L14"
    },
    {
      "after_item": "S4_INGEST",
      "title_raw": "마. 기타 의사의 주의사항",
      "reason": "코드없음",
      "statements": [
        {
          "value": "의료인력이 해당물질에 대해 인지하고 보호조치를 취하도록 하시오"
        ,
          "line": "p2:L20"
        }
      ]
    ,
      "suggested_code": "S4_DOCTOR"
    ,
      "line": "p2:L20"
    }
  ]
}

